function cpcc_qc_term($code,$rtl){$map=array('pass'=>array('ناجح','Pass'),'fail'=>array('راسب','Fail'),'not_applicable'=>array('لا ينطبق','N/A'),'pending'=>array('معلّق','Pending'),'pending_corrective_action'=>array('بانتظار الإجراء التصحيحي','Pending corrective action'),'reinspection_required'=>array('إعادة فحص مطلوبة','Reinspection required'),'critical'=>array('حرج','Critical'),'major'=>array('رئيسي','Major'),'minor'=>array('بسيط','Minor'),'none'=>array('بدون','None'));return isset($map[$code])?$map[$code][$rtl?0:1]:str_replace('_',' ',(string)$code);}
function cpcc_qc_icon($code){return $code==='pass'?'✓':($code==='fail'?'✕':($code==='not_applicable'?'—':'!'));}
$pageCss=array('/custom/chinaplanetcustomercenter/css/customer_dashboard.css','/custom/chinaplanetcustomercenter/css/operations.css');
