<?php if($isQc){$qc=$report['qc_publication'];$inspection=$qc['inspection'];$summary=$qc['summary'];$pdfUrl=cpcc_portal_scoped_url('/chinaplanetcustomercenter/qc_pdf.php',$isExternal,$socid,array('report'=>$report['qc_public_uuid'])); ?>
<section class="cpcc-operational-cards" aria-label="<?php echo $rtl?'ملخص تقرير الجودة':'QC report summary'; ?>"><div class="cpcc-card"><span><?php echo $rtl?'النتيجة النهائية':'Overall result'; ?></span><strong><?php echo dol_escape_htmltag(cpcc_qc_term($qc['overall_result'],$rtl)); ?></strong></div><div class="cpcc-card"><span><?php echo $rtl?'إصدار التقرير':'Report version'; ?></span><strong>v<?php echo (int)$qc['version']; ?></strong></div><div class="cpcc-card"><span><?php echo $rtl?'تاريخ الفحص':'Inspected'; ?></span><strong><?php echo !empty($inspection['inspected_at'])?dol_escape_htmltag(dol_print_date($inspection['inspected_at'],'dayhour')):'—'; ?></strong></div><div class="cpcc-card"><span><?php echo $rtl?'تاريخ الاعتماد':'Published'; ?></span><strong><?php echo !empty($inspection['published_at'])?dol_escape_htmltag(dol_print_date($inspection['published_at'],'dayhour')):'—'; ?></strong></div></section>
<section class="cpcc-qc-summary" aria-label="<?php echo $rtl?'أعداد نقاط الفحص':'Checkpoint counts'; ?>"><span><?php echo cpcc_qc_term('pass',$rtl); ?> <b><?php echo (int)$summary['pass']; ?></b></span><span><?php echo cpcc_qc_term('fail',$rtl); ?> <b><?php echo (int)$summary['fail']; ?></b></span><span><?php echo cpcc_qc_term('not_applicable',$rtl); ?> <b><?php echo (int)$summary['not_applicable']; ?></b></span><span><?php echo cpcc_qc_term('critical',$rtl); ?> <b><?php echo (int)$summary['critical']; ?></b></span><span><?php echo cpcc_qc_term('major',$rtl); ?> <b><?php echo (int)$summary['major']; ?></b></span><span><?php echo cpcc_qc_term('minor',$rtl); ?> <b><?php echo (int)$summary['minor']; ?></b></span></section>
