<?php $failures=array();foreach($qc['sections']as$section)foreach($section['checkpoints']as$checkpoint)if($checkpoint['result']==='fail')$failures[]=$checkpoint;if($failures){ ?><nav class="cpcc-qc-failures" aria-label="<?php echo $rtl?'روابط نقاط الفشل':'Failure links'; ?>"><strong><?php echo $rtl?'انتقل إلى نقاط الفشل:':'Jump to failed checkpoints:'; ?></strong><?php foreach($failures as$failure){ ?><a href="#qc-checkpoint-<?php echo dol_escape_htmltag($failure['id']); ?>"><?php echo dol_escape_htmltag($failure['requirement']); ?></a><?php } ?></nav><?php } ?>
