'));if($evidence['kind']==='video'){ ?><figure><video controls preload="metadata"><source src="<?php echo dol_escape_htmltag($mediaUrl); ?>" type="<?php echo dol_escape_htmltag($evidence['mime_type']); ?>"><?php echo $rtl?'متصفحك لا يدعم الفيديو.':'Your browser cannot play this video.'; ?></video><figcaption><?php echo dol_escape_htmltag($caption); ?> · <a href="<?php echo dol_escape_htmltag($mediaUrl); ?>" download><?php echo $rtl?'تنزيل آمن':'Secure download'; ?></a></figcaption></figure><?php }else{ ?><figure><a href="<?php echo dol_escape_htmltag($mediaUrl); ?>" target="_blank" rel="noopener"><img loading="lazy" src="<?php echo dol_escape_htmltag($mediaUrl); ?>" alt="<?php echo dol_escape_htmltag($caption); ?>"></a><figcaption><?php echo dol_escape_htmltag($caption); ?></figcaption></figure><?php }} ?></div></article><?php } ?></section><?php } ?>
<?php }else{ ?>
<section class="cpcc-operational-cards"><div class="cpcc-card"><span>الحالة / Status</span><strong><?php echo dol_escape_htmltag($langs->trans('Stage_'.$report['stage'])); ?></strong></div><div class="cpcc-card"><span>الإجراء التالي / Next action</span><strong><?php echo dol_escape_htmltag($report['next_action']?:'—'); ?></strong></div><div class="cpcc-card"><span>الموعد / Deadline</span><strong><?php echo $report['date_deadline']?dol_escape_htmltag(dol_print_date($report['date_deadline'],'dayhour')):'—'; ?></strong></div></section>
<?php if($report['note_public']){ ?><section class="cpcc-section-head"><div><h2>ملخص التقرير</h2><p><?php echo nl2br(dol_escape_htmltag($report['note_public'])); ?></p></div></section><?php } ?>
<section class="cpcc-section-head"><div><h2>تفاصيل التقرير</h2><p>لا تعرض هذه الصفحة أي ملاحظات داخلية أو تكاليف موردين.</p></div></section><div class="cpcc-table-wrap"><table class="cpcc-table"><tbody><?php foreach($report['service_data'] as $field=>$value)if(isset($allowed[$field])&&trim((string)$value)!==''){ ?><tr><th><?php echo dol_escape_htmltag($langs->trans('Field_'.$field)); ?></th><td><?php echo nl2br(dol_escape_htmltag($value)); ?></td></tr><?php } ?></tbody></table></div>
